$ErrorActionPreference='Stop';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path (Split-Path -Parent $ScriptDir) 'lib/common.ps1');$major=8;$installDir=if($env:DOTNET_INSTALL_DIR){$env:DOTNET_INSTALL_DIR}else{Join-Path $HOME '.dotnet'}
if(Test-Command dotnet){$v=& dotnet --version;if((Get-Version $v).Split('.')[0]-as[int] -ge $major){Write-Ok ".NET $v ya instalado";exit 0}}
$tmp=Join-Path $env:TEMP ("dotnet-install-"+[guid]::NewGuid());New-Item -ItemType Directory -Path $tmp -Force|Out-Null;$file=Join-Path $tmp 'dotnet-install.ps1';Invoke-WebRequest https://dot.net/v1/dotnet-install.ps1 -OutFile $file;& $file -Channel '8.0' -InstallDir $installDir -NoPath;$env:PATH="$installDir;$env:PATH";Ensure-PathLine "`$env:PATH = `"$installDir;`$env:PATH`"" (Get-UserProfile);$tools=Join-Path $HOME '.dotnet	ools';$env:PATH="$tools;$env:PATH";Ensure-PathLine "`$env:PATH = `"$tools;`$env:PATH`"" (Get-UserProfile)
foreach($tool in 'dotnet-ef','dotnet-format'){if(-not((& dotnet tool list --global 2>$null)|Select-String ([regex]::Escape($tool)))){& dotnet tool install --global $tool}};$v=& dotnet --version;if(-not(Test-VersionGE $v '8.0.100')){throw ".NET $v < 8.0.100"};Write-Ok ".NET SDK $v instalado"
